"""E4 route (a): Kurisu-voiced native Mandarin, generated by the Base model.

Replay rows teach "language id => native phonetics" with *other* voices, but the Kurisu
row itself only ever hears Japanese, so speaker and language stay confounded
(finetune_methods_2026-10.md s4). These rows put native-sounding Mandarin under the
Kurisu speaker vector:

  Base model, x-vector-only, Kurisu's locked vector (mean of build_v3/ref_kurisu.txt,
  computed exactly as train_sft.speaker_embedding), language "Chinese", non-streaming,
  upstream sampling defaults, 2 samples per text.

Texts: AISHELL-3 *test* transcripts (the replay set uses train only), 8-30 hanzi.
Texts with numerals are left out (the ASR writes digits), as are texts that also
occur in AISHELL-3 train (the replay pool).
A sample is kept only if (all automatic, pre-registered here):
  - VoxLingua107 P(zh) >= 0.9 (accent_metrics.lid_scores);
  - Qwen3-ASR (forced Chinese, v3 text normalisation) CER <= 0.05;
  - 2-12 s long and not a runaway (metrics.is_runaway);
  - ECAPA similarity to the real-Kurisu centroid >= the 25th percentile of these
    Base Mandarin samples themselves (real Japanese takes would be the wrong floor:
    the same voice scores lower across languages, so that floor would favour the most
    Japanese-sounding samples).
Among a text's passing samples the most Kurisu-like (highest similarity) is kept,
then trimmed/padded/loudness-normalised with v2's audio policy.

Run only if E0 shows Base condition B is at least halfway from v2 (F) to the native
anchor (D) on the language-ID log-ratio; otherwise this route would teach the accent.
Writes pseudo/pseudo_rows.jsonl {id, audio, text, language: chinese, speaker: kurisu,
split, dur, source: pseudo_base, p_zh, cer, sim}.
"""
from __future__ import annotations

import argparse
import json
import os
import random
from pathlib import Path

import numpy as np
import soundfile as sf
import torch

WORK = Path(os.environ.get("KURISU_WORK", "/workspace/kurisu"))
BASE = "Qwen/Qwen3-TTS-12Hz-1.7B-Base"
BATCH = 12


def texts(n: int, seed: int) -> list[tuple[str, str]]:
    import p05_replay as RP
    repo = "shenyunhang/AISHELL-3"
    rev = RP.ZH_REPOS[repo]
    meta = RP.CACHE / "zh_meta" / repo.replace("/", "__")
    content = RP.zh_parse_content(RP.cached_get([RP.hf_resolve(repo, rev, "test/content.txt")],
                                                meta / "test/content.txt", "zh_meta").decode("utf-8"))
    train = RP.zh_parse_content(RP.cached_get([RP.hf_resolve(repo, rev, "train/content.txt")],
                                              meta / "train/content.txt", "zh_meta").decode("utf-8"))
    train_texts = {h for h, _ in train.values() if h}
    numerals = set("零〇一二三四五六七八九十百千万亿两")
    pool = sorted((u, h) for u, (h, why) in content.items()
                  if h and 8 <= len(h) <= 30 and h not in train_texts
                  and sum(c in numerals for c in h) <= 1)
    seen, out = set(), []
    random.Random(seed).shuffle(pool)
    for u, h in pool:
        if h not in seen:
            seen.add(h)
            out.append((u, h + ("？" if h.endswith("吗") else "。")))
        if len(out) >= n:
            break
    return out


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--n_texts", type=int, default=900)
    ap.add_argument("--samples", type=int, default=2)
    ap.add_argument("--seed", type=int, default=31)
    args = ap.parse_args()

    import accent_metrics
    import metrics
    import p03_build as V2
    import pyloudnorm
    from qwen_tts import Qwen3TTSModel
    from qwen_tts.inference.qwen3_tts_model import VoiceClonePromptItem

    import p06_eval_v3
    import train_sft

    out_dir = WORK / "pseudo"
    raw_dir, wav_dir = out_dir / "raw", out_dir / "wavs"
    raw_dir.mkdir(parents=True, exist_ok=True)
    wav_dir.mkdir(parents=True, exist_ok=True)
    items = texts(args.n_texts, args.seed)

    base = Qwen3TTSModel.from_pretrained(BASE, device_map="cuda:0", dtype=torch.bfloat16,
                                         attn_implementation="sdpa")
    refs = train_sft.ref_paths(WORK / "build_v3" / "ref_kurisu.txt")
    vec = train_sft.speaker_embedding(base.model, "kurisu", refs, "cuda:0", torch.bfloat16)[0]
    prompt = VoiceClonePromptItem(ref_code=None, ref_spk_embedding=vec,
                                  x_vector_only_mode=True, icl_mode=False)
    manifest = []
    for s in range(args.samples):
        for b in range(0, len(items), BATCH):
            chunk = items[b:b + BATCH]
            torch.manual_seed(70000 + 1000 * s + b)
            wavs, sr = base.generate_voice_clone(
                text=[t for _, t in chunk], language=["Chinese"] * len(chunk),
                voice_clone_prompt=[prompt] * len(chunk), max_new_tokens=400,
                non_streaming_mode=True)
            for (u, t), w in zip(chunk, wavs):
                f = f"{u}_s{s}.wav"
                sf.write(str(raw_dir / f), np.asarray(w, dtype=np.float32), sr)
                manifest.append({"pid": f"{u}_s{s}", "utt": u, "text": t, "lang": "zh",
                                 "file": f, "kind": "pseudo"})
    del base
    torch.cuda.empty_cache()
    (raw_dir / "manifest.jsonl").write_text(
        "".join(json.dumps(m, ensure_ascii=False) + "\n" for m in manifest), encoding="utf-8")

    centroid = p06_eval_v3.centroid()
    metrics.score_dir(raw_dir, centroid, text_norm="v3")
    scored = {r["pid"]: r for r in (json.loads(l) for l in (raw_dir / "scored.jsonl").read_text(encoding="utf-8").splitlines() if l)}
    acc = accent_metrics.score_dir(raw_dir, raw_dir / "manifest.jsonl")
    acc_rows = {r["pid"]: r for r in (json.loads(l) for l in (raw_dir / "scored_accent.jsonl").read_text(encoding="utf-8").splitlines() if l)}
    sim_floor = float(np.percentile([r["sim"] for r in scored.values()], 25))

    def p_zh(r):
        for key in ("p_target", "p_zh", "lid_p_target"):
            if r.get(key) is not None:
                return float(r[key])
        raise KeyError(f"no P(zh) field in accent row: {sorted(r)}")

    best: dict[str, dict] = {}
    for pid, r in scored.items():
        a = acc_rows.get(pid)
        if a is None:
            continue
        r = {**r, "p_zh": p_zh(a)}
        ok = (r["p_zh"] >= 0.9 and r["cer"] <= 0.05 and r["sim"] >= sim_floor
              and 2.0 <= r["dur"] <= 12.0 and not metrics.is_runaway(r))
        if not ok:
            continue
        cur = best.get(r["utt"])
        if cur is None or r["sim"] > cur["sim"]:
            best[r["utt"]] = r

    meter = pyloudnorm.Meter(V2.SR)
    rows = []
    rng = random.Random(args.seed)
    for u, r in sorted(best.items()):
        wav, sr = sf.read(str(raw_dir / r["file"]), dtype="float32", always_2d=False)
        if sr != V2.SR:
            raise SystemExit(f"{r['file']}: {sr} Hz")
        new, _ = V2.normalise_audio(wav, meter)
        if new is None:
            continue
        path = wav_dir / f"pseudo_zh_{u}.wav"
        sf.write(str(path), new, V2.SR, subtype="PCM_16")
        rows.append({"id": f"pseudo_zh_{u}", "audio": str(path), "text": r["text"],
                     "language": "chinese", "speaker": "kurisu",
                     "split": "val" if rng.random() < 0.03 else "train",
                     "dur": round(len(new) / V2.SR, 3), "source": "pseudo_base",
                     "p_zh": round(r["p_zh"], 4), "cer": r["cer"], "sim": r["sim"]})
    (out_dir / "pseudo_rows.jsonl").write_text(
        "".join(json.dumps(r, ensure_ascii=False) + "\n" for r in rows), encoding="utf-8")
    report = {"texts": len(items), "samples": len(manifest), "kept": len(rows),
              "kept_hours": round(sum(r["dur"] for r in rows) / 3600, 3),
              "sim_floor": round(sim_floor, 4),
              "pass_rate": round(len(best) / max(1, len(items)), 3),
              "accent_summary": acc.get("all")}
    (out_dir / "report.json").write_text(json.dumps(report, indent=2, ensure_ascii=False), encoding="utf-8")
    print(json.dumps(report, indent=2, ensure_ascii=False))


if __name__ == "__main__":
    main()
